  -- Check JWT metadata (Fast & Safe)
  IF (auth.jwt() -> 'app_metadata' -> 'assigned_houses') @> jsonb_build_array(p_house_id::text) THEN
    RETURN true;
  END IF;

  -- Fallback to DB (Safe because it's a direct ID lookup)
